declare(strict_types=1);require_once __DIR__.'/../../includes/api.php';cmsApiBootstrap();require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../includes/module-registry.php';$pdo=cmsPdo();if(!cmsModuleEnabled($pdo,'contact'))cmsJson(['ok'=>false,'error'=>'MODULE_DISABLED'],404);
if($_SERVER['REQUEST_METHOD']==='GET'){cmsJson(['ok'=>true,'data'=>['email'=>(string)cmsSetting('contact_email','',$pdo),'phone'=>(string)cmsSetting('contact_phone','',$pdo),'whatsapp'=>(string)cmsSetting('contact_whatsapp','',$pdo),'whatsapp_enabled'=>cmsBool(cmsSetting('contact_whatsapp_enabled','0',$pdo))===1]]);}
if($_SERVER['REQUEST_METHOD']!=='POST')cmsJson(['ok'=>false,'error'=>'METHOD_NOT_ALLOWED'],405);$d=str_contains((string)($_SERVER['CONTENT_TYPE']??''),'application/json')?cmsRequestJson():$_POST;$name=cmsStr($d['name']??'',190);$email=cmsStr($d['email']??'',190);$phone=cmsStr($d['phone']??'',80);$subject=cmsStr($d['subject']??'',255);$message=cmsStr($d['message']??'',5000);if($name===''||$message===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))cmsJson(['ok'=>false,'error'=>'VALIDATION_ERROR'],422);
$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');$secret=(string)(cmsConfig()['app_key']?:cmsConfig()['app_name']);$fp=hash_hmac('sha256',$ip,$secret);$now=new DateTimeImmutable('now');$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT * FROM contact_rate_limits WHERE fingerprint=:f FOR UPDATE');$s->execute([':f'=>$fp]);$r=$s->fetch();$count=0;$start=$now;$last=null;if($r){$start=new DateTimeImmutable($r['window_started_at']);$last=$r['last_request_at']?new DateTimeImmutable($r['last_request_at']):null;if($now->getTimestamp()-$start->getTimestamp()<600)$count=(int)$r['request_count'];else{$count=0;$start=$now;}if($last&&$now->getTimestamp()-$last->getTimestamp()<8)throw new RuntimeException('RATE');}if($count>=5)throw new RuntimeException('RATE');$up=$pdo->prepare('INSERT INTO contact_rate_limits(fingerprint,window_started_at,request_count,last_request_at) VALUES(:f,:w,1,:l) ON DUPLICATE KEY UPDATE window_started_at=VALUES(window_started_at),request_count=:c,last_request_at=VALUES(last_request_at)');$up->execute([':f'=>$fp,':w'=>$start->format('Y-m-d H:i:s'),':l'=>$now->format('Y-m-d H:i:s'),':c'=>$count+1]);$q=$pdo->prepare('INSERT INTO contact_messages(name,email,phone,subject,message,status) VALUES(:n,:e,:p,:s,:m,"new")');$q->execute([':n'=>$name,':e'=>$email?:null,':p'=>$phone?:null,':s'=>$subject?:null,':m'=>$message]);$pdo->commit();cmsJson(['ok'=>true]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e->getMessage()==='RATE')cmsJson(['ok'=>false,'error'=>'RATE_LIMITED'],429);cmsJson(['ok'=>false,'error'=>'CONTACT_ERROR'],500);}
